"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { justifyRows } from "./salon-layout";

export type SalonItem = {
  /** Intrinsic image URL. Omit to render a typographic placard in the same slot. */
  src?: string;
  /** Intrinsic pixel width — drives the aspect ratio, not the render size. */
  width: number;
  /** Intrinsic pixel height. */
  height: number;
  /** Where clicking the piece goes. Internal hrefs route through `linkComponent`. */
  href?: string;
  /** Alt text / accessible name for the piece. */
  alt?: string;
  /** A placard shown over the piece on hover/focus (and the placard's own text when `src` is absent). */
  title?: React.ReactNode;
  /** External destination — opens in a new tab and always renders a plain `<a>`. */
  external?: boolean;
};

export type SalonProps = {
  /** The pieces to hang, each at its own aspect ratio. */
  items: SalonItem[];
  /** Target row height rows are justified around — the effective minimum piece size. Defaults to 260. */
  targetRowHeight?: number;
  /** Gap between pieces (and rows) in px. Defaults to 12. */
  gap?: number;
  /** Container max width in px. Defaults to unbounded (fills its parent). */
  maxWidth?: number;
  /** Assumed width for the first (server) render, before the container is measured. Defaults to 1040. */
  assumedWidth?: number;
  /** Router link for internal hrefs (e.g. next/link). Defaults to a plain `<a>`. External hrefs always stay `<a>`. */
  linkComponent?: React.ElementType;
  /** Accessible name for the wall region. */
  ariaLabel?: string;
  className?: string;
};

// Layout must settle before paint on the client, but useLayoutEffect warns
// during SSR; fall back to useEffect on the server render.
const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect;

/**
 * A salon hang: a wall of images shown at their own aspect ratios, packed into
 * justified rows that fill the width.
 *
 * `gallery` is the uniform searchable grid — every project the same card, sized
 * to a column. `shelf` is one horizontal row you skim. A salon is neither: the
 * pieces keep their real proportions, a tall poster next to a wide banner next
 * to a square, and the point is the varied hang itself. It is what you reach for
 * when the images *are* the content and their shapes carry meaning.
 *
 * Rows are justified to span the width, with the row height kept near
 * `targetRowHeight` — the effective minimum piece size — so the wall reads full
 * rather than ragged and pieces never shrink away to fit. The one exception is
 * the trailing leftover row, which fills only if it nearly does and is otherwise
 * capped so a stray piece sits at a sane size instead of stretching across.
 * Nothing is ever cropped (see `Piece`). The container is measured with a
 * ResizeObserver so the hang reflows on resize; the first paint uses
 * `assumedWidth` so server and client markup agree before that measurement lands.
 */
export function Salon({
  items,
  targetRowHeight = 260,
  gap = 12,
  maxWidth,
  assumedWidth = 1040,
  linkComponent,
  ariaLabel,
  className,
}: SalonProps) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [width, setWidth] = React.useState(assumedWidth);

  useIsomorphicLayoutEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const measure = () => {
      const w = el.clientWidth;
      if (w > 0) setWidth(w);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const rows = React.useMemo(
    () => justifyRows(items, width, gap, targetRowHeight),
    [items, width, gap, targetRowHeight],
  );

  return (
    <div
      ref={containerRef}
      role="group"
      aria-label={ariaLabel}
      className={cn("flex w-full flex-col", className)}
      style={{ gap, maxWidth }}
    >
      {rows.map((row, ri) => (
        <div key={ri} className="flex" style={{ gap }}>
          {row.items.map((item, ii) => (
            <Piece
              key={item.src ?? `${ri}-${ii}`}
              item={item}
              width={row.height * (item.width / item.height)}
              height={row.height}
              linkComponent={linkComponent}
            />
          ))}
        </div>
      ))}
    </div>
  );
}

function Piece({
  item,
  width,
  height,
  linkComponent,
}: {
  item: SalonItem;
  width: number;
  height: number;
  linkComponent?: React.ElementType;
}) {
  const isExternal = item.external || /^https?:\/\//.test(item.href ?? "");
  const Link = !isExternal && item.href && linkComponent ? linkComponent : "a";

  const inner = (
    <>
      {item.src ? (
        // Intrinsic width/height give the browser the true aspect ratio — a
        // viewBox-only SVG otherwise has no intrinsic size and object-fit falls
        // back to 300x150, cropping. object-contain guarantees the whole piece
        // shows: the box is already the image's aspect, so it fills edge to
        // edge, and any dimension mismatch letterboxes rather than crops.
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={item.src}
          alt={item.alt ?? ""}
          width={item.width}
          height={item.height}
          loading="lazy"
          draggable={false}
          className="block h-full w-full object-contain"
        />
      ) : (
        <div className="flex h-full w-full items-center justify-center px-4 text-center font-mono text-xs lowercase tracking-wide text-white/50">
          {item.title ?? item.alt ?? "untitled"}
        </div>
      )}
      {item.title && (
        <span
          className={cn(
            "pointer-events-none absolute inset-x-0 bottom-0 truncate bg-gradient-to-t from-black/85 to-transparent px-2.5 pb-1.5 pt-6",
            "text-sm lowercase text-white opacity-0 transition-opacity duration-200",
            "group-hover:opacity-100 group-focus-visible:opacity-100 motion-reduce:transition-none",
          )}
        >
          {item.title}
        </span>
      )}
    </>
  );

  const boxClass = cn(
    // Border is transparent until hover/focus (it still reserves its 1px so the
    // layout doesn't shift), so at rest the pieces read as a clean wall.
    "group relative block shrink-0 overflow-hidden border border-transparent bg-white/[0.02]",
    "outline-none transition-colors duration-200 hover:border-white/40 focus-visible:border-white/60 motion-reduce:transition-none",
  );
  const style: React.CSSProperties = { width, height };

  if (!item.href) {
    return (
      <div className={boxClass} style={style} aria-label={item.alt}>
        {inner}
      </div>
    );
  }

  return (
    <Link
      href={item.href}
      aria-label={item.alt || (typeof item.title === "string" ? item.title : undefined)}
      className={boxClass}
      style={style}
      {...(isExternal ? { target: "_blank", rel: "noopener noreferrer" } : {})}
    >
      {inner}
    </Link>
  );
}

// Pure row packing for `salon`, extracted so the geometry can be tested without
// a DOM. This is the justified-gallery algorithm: pieces keep their aspect and
// each row is scaled to fill the container width, so rows read full rather than
// ragged. Row height stays near `targetHeight` — the effective minimum piece
// size — by choosing, at each break, whether including the next piece or
// deferring it lands closer to the target. What gets sacrificed to fill is the
// row's exact width via a small height wobble, never the piece size shrinking
// away; only the trailing leftover row is capped so a lone piece can't balloon.

export type Sized = { width: number; height: number };
export type JustifiedRow<T> = { items: T[]; height: number };

/**
 * Pack `items` into justified rows that each fill `containerWidth`.
 *
 * Rows accumulate pieces until adding the next would pull the fill height below
 * `targetHeight`; at that point the row closes on whichever side (with or
 * without the piece) sits closer to the target, keeping every full row near the
 * target height and spanning the width. The final, leftover row fills only if it
 * nearly does on its own, and is otherwise capped at `targetHeight * 1.3` so a
 * stray piece sits at a sane size instead of stretching across. Pieces with a
 * non-positive or non-finite aspect ratio are skipped.
 */
export function justifyRows<T extends Sized>(
  items: T[],
  containerWidth: number,
  gap: number,
  targetHeight: number,
): JustifiedRow<T>[] {
  const rows: JustifiedRow<T>[] = [];
  let row: { item: T; ar: number }[] = [];
  let arSum = 0;

  const fillHeight = (count: number, aspectSum: number) =>
    (containerWidth - gap * (count - 1)) / aspectSum;

  const close = (entries: { item: T; ar: number }[], height: number) =>
    rows.push({ items: entries.map((e) => e.item), height });

  for (const item of items) {
    const ar = item.width / item.height;
    if (!Number.isFinite(ar) || ar <= 0) continue;

    const heightWith = fillHeight(row.length + 1, arSum + ar);
    if (row.length > 0 && heightWith < targetHeight) {
      const heightWithout = fillHeight(row.length, arSum);
      if (targetHeight - heightWith <= heightWithout - targetHeight) {
        // Including the piece lands closer to the target — keep it, close here.
        row.push({ item, ar });
        close(row, heightWith);
      } else {
        // Deferring lands closer — close without it, carry it to the next row.
        close(row, heightWithout);
        row = [{ item, ar }];
        arSum = ar;
        continue;
      }
      row = [];
      arSum = 0;
    } else {
      row.push({ item, ar });
      arSum += ar;
    }
  }

  if (row.length) {
    const height = Math.min(fillHeight(row.length, arSum), targetHeight * 1.3);
    close(row, height);
  }

  return rows;
}
